import{_ as n,C as r,o as p,c,ao as s,j as i,a as t,E as o,w as l}from"./chunks/framework.xfSQTa7I.js";const m="/ParallelStencil.jl/v0.17/assets/T_eff.YMkX6GlG.png",y=JSON.parse('{"title":"Concise single/multi-xPU miniapps","description":"","frontmatter":{},"headers":[],"relativePath":"miniapps.md","filePath":"miniapps.md","lastUpdated":null}'),u={name:"miniapps.md"};function h(d,e,f,g,b,v){const a=r("CitationPreview");return p(),c("div",null,[e[20]||(e[20]=s('<h1 id="Concise-single/multi-xPU-miniapps" tabindex="-1">Concise single/multi-xPU miniapps <a class="header-anchor" href="#Concise-single/multi-xPU-miniapps" aria-label="Permalink to &quot;Concise single/multi-xPU miniapps {#Concise-single/multi-xPU-miniapps}&quot;">​</a></h1><p>The miniapps regroup a collection of various 2-D and 3-D codes that leverage ParallelStencil to implement architecture-agnostic high-level code for parallel high-performance stencil computations on GPUs and CPUs. The miniapps target various challenging domain science case studies where multi-physics coupling and important nonlinearities challenge existing solving strategies. In most cases, second order pseudo-transient relaxation delivers implicit solutions of the differential equations. Some miniapps feature a multi-xPU version, which combines the capabilities of ParallelStencil and <a href="https://github.com/eth-cscs/ImplicitGlobalGrid.jl" target="_blank" rel="noreferrer">ImplicitGlobalGrid.jl</a> in order to enable multi-GPU and multi-CPU executions, unleashing <em>Julia-at-scale</em>.</p><h2 id="performance-metric" tabindex="-1">Performance metric <a class="header-anchor" href="#performance-metric" aria-label="Permalink to &quot;Performance metric {#performance-metric}&quot;">​</a></h2>',3)),i("p",null,[e[1]||(e[1]=t("Many-core processors as GPUs are throughput-oriented systems that use their massive parallelism to hide latency. On the scientific application side, most algorithms require only a few operations or flops compared to the amount of numbers or bytes accessed from main memory, and thus are significantly memory bound. The Flop/s metric is no longer the most adequate for reporting the application performance of many modern applications. This status motivated us to develop a memory throughput-based performance evaluation metric, ",-1)),e[2]||(e[2]=i("code",null,"T_eff",-1)),e[3]||(e[3]=t(", to evaluate the performance of iterative stencil-based solvers [",-1)),o(a,null,{default:l(()=>[...e[0]||(e[0]=[i("a",{id:"Omlin2020JuliaCon-cite-6"},null,-1),i("a",{href:"/ParallelStencil.jl/v0.17/references#Omlin2020JuliaCon"},"4",-1)])]),_:1}),e[4]||(e[4]=t("].",-1))]),e[21]||(e[21]=i("p",null,[t("The effective memory access, "),i("code",null,"A_eff"),t(" [GB], is the sum of twice the memory footprint of the unknown fields, "),i("code",null,"D_u"),t(", (fields that depend on their own history and that need to be updated every iteration) and the known fields, "),i("code",null,"D_k"),t(", that do not change every iteration. The effective memory access divided by the execution time per iteration, "),i("code",null,"t_it"),t(" [sec], defines the effective memory throughput, "),i("code",null,"T_eff"),t(" [GB/s]: "),i("img",{src:m,alt:"Effective memory throughput metric",style:{display:"block",margin:"auto",width:"100%","max-width":"360px"}})],-1)),i("p",null,[e[6]||(e[6]=t("The upper bound of ",-1)),e[7]||(e[7]=i("code",null,"T_eff",-1)),e[8]||(e[8]=t(" is ",-1)),e[9]||(e[9]=i("code",null,"T_peak",-1)),e[10]||(e[10]=t(" as measured e.g. by the STREAM benchmark [",-1)),o(a,null,{default:l(()=>[...e[5]||(e[5]=[i("a",{id:"McCalpin1995-cite-1"},null,-1),i("a",{href:"/ParallelStencil.jl/v0.17/references#McCalpin1995"},"8",-1)])]),_:1}),e[11]||(e[11]=t("] for CPUs or a GPU analogue. Defining the ",-1)),e[12]||(e[12]=i("code",null,"T_eff",-1)),e[13]||(e[13]=t(" metric, we assume that 1) we evaluate an iterative stencil-based solver, 2) the problem size is much larger than the cache sizes and 3) the usage of time blocking is not feasible or advantageous (which is a reasonable assumption for real-world applications). An important concept is not to include fields within the effective memory access that do not depend on their own history (e.g. fluxes); such fields can be re-computed on the fly or stored on-chip. Defining a theoretical upper bound for ",-1)),e[14]||(e[14]=i("code",null,"T_eff",-1)),e[15]||(e[15]=t(" that is closer to the real upper bound is work in progress.",-1))]),e[22]||(e[22]=s('<p>Using simple array broadcasting capabilities both with GPU and CPU arrays within Julia does not enable close to optimal performance; ParallelStencil.jl permits to overcome this limitation (see the <a href="./overview">Overview</a>) at similar ease of programming.</p><h2 id="Running-the-miniapps" tabindex="-1">Running the miniapps <a class="header-anchor" href="#Running-the-miniapps" aria-label="Permalink to &quot;Running the miniapps {#Running-the-miniapps}&quot;">​</a></h2><p>All miniapp codes follow a similar structure and permit serial and threaded CPU as well as Nvidia GPU execution. The first line of each miniapp code permits to enable the CUDA.jl GPU backend upon setting the <code>USE_GPU</code> flag to <code>true</code>.</p><p>All the miniapps can be interactively executed within the <a href="https://docs.julialang.org/en/v1/stdlib/REPL/" target="_blank" rel="noreferrer">Julia REPL</a> (this includes the multi-xPU versions when using a single CPU or GPU). Note that for optimal performance the miniapp script of interest <code>&lt;miniapp_code&gt;</code> should be launched from the shell using the project&#39;s dependencies <code>--project</code>, disabling array bound checking <code>--check-bounds=no</code>, and using optimization level 3 <code>-O3</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check-bounds=no</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">miniapp_cod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.jl</span></span></code></pre></div><p>Refer to the documentation of your supercomputing centre for instructions to run Julia at scale, e.g. for the <a href="https://docs.cscs.ch/software/prgenv/julia/" target="_blank" rel="noreferrer">Alps supercomputer at the Swiss National Supercomputing Centre (CSCS)</a>. Whether CUDA-aware or ROCm-aware MPI works on a system can be checked with the GPU examples of <a href="https://github.com/JuliaParallel/MPI.jl/tree/master/docs/examples" target="_blank" rel="noreferrer">MPI.jl</a> (e.g. <code>alltoall_test_cuda.jl</code> or <code>alltoall_test_rocm.jl</code>).</p><h2 id="Thermo-mechanical-convection-2-D-app" tabindex="-1">Thermo-mechanical convection 2-D app <a class="header-anchor" href="#Thermo-mechanical-convection-2-D-app" aria-label="Permalink to &quot;Thermo-mechanical convection 2-D app {#Thermo-mechanical-convection-2-D-app}&quot;">​</a></h2><blockquote><p>app: <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/ThermalConvection2D.jl" target="_blank" rel="noreferrer">ThermalConvection2D.jl</a></p></blockquote><p>This thermal convection example in 2-D combines a viscous Stokes flow to advection-diffusion of heat including a temperature-dependent shear viscosity. The miniapp resolves thermal convection cells (e.g. Earth&#39;s mantle convection and plumes): <img src="https://raw.githubusercontent.com/omlins/ParallelStencil.jl/main/miniapps/ThermalConvect2D.gif" alt="Thermal convection 2-D" style="display:block;margin:auto;width:100%;max-width:560px;"></p><p><em>The gif depicts non-dimensional temperature field as evolving into convection cells and plumes.</em></p><h2 id="Viscous-Stokes-2-D-app" tabindex="-1">Viscous Stokes 2-D app <a class="header-anchor" href="#Viscous-Stokes-2-D-app" aria-label="Permalink to &quot;Viscous Stokes 2-D app {#Viscous-Stokes-2-D-app}&quot;">​</a></h2><blockquote><p>app: <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/Stokes2D.jl" target="_blank" rel="noreferrer">Stokes2D.jl</a></p></blockquote><p>The viscous Stokes flow example solves the incompressible Stokes equations with linear shear rheology in 2-D. The model configuration represents a buoyant inclusion within a less buoyant matrix: <img src="https://raw.githubusercontent.com/omlins/ParallelStencil.jl/main/miniapps/Stokes2D.gif" alt="Viscous Stokes 2-D" style="display:block;margin:auto;width:100%;max-width:560px;"></p><p><em>The figure depicts - Upper panels: the dynamical pressure field, the vertical Vy velocity. Lower panels: the log10 of the vertical momentum balance residual Ry and the log10 of the error norm evolution as function of pseudo-transient iterations.</em></p><h2 id="Viscous-Stokes-3-D-app" tabindex="-1">Viscous Stokes 3-D app <a class="header-anchor" href="#Viscous-Stokes-3-D-app" aria-label="Permalink to &quot;Viscous Stokes 3-D app {#Viscous-Stokes-3-D-app}&quot;">​</a></h2><blockquote><p>apps: <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/Stokes3D.jl" target="_blank" rel="noreferrer">Stokes3D.jl</a>, <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/stokes_multixpu/Stokes3D_multixpu.jl" target="_blank" rel="noreferrer">Stokes3D_multixpu.jl</a></p></blockquote><p>The viscous Stokes flow example solves the incompressible Stokes equations with linear shear rheology in 3-D. The model configuration represents a buoyant spherical inclusion within a less buoyant matrix: <img src="https://raw.githubusercontent.com/omlins/ParallelStencil.jl/main/miniapps/stokes_multixpu/Stokes3D.gif" alt="Viscous Stokes 3-D multi-xPU" style="display:block;margin:auto;width:100%;max-width:560px;"></p><p><em>The figure depicts vertically sliced cross-sections of - Upper panels: the dynamical pressure field, the vertical Vz velocity. Lower panels: the log10 of the vertical momentum balance residual Rz and the log10 of the error norm evolution as function of pseudo-transient iterations. <strong>The numerical resolution is 252x252x252 grid points in 3-D on 8 GPUs (i.e. a local domain size of 127x127x127 per GPU).</strong></em></p><p>The <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/Stokes3D.jl" target="_blank" rel="noreferrer">Stokes3D.jl</a> and <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/stokes_multixpu/Stokes3D_multixpu.jl" target="_blank" rel="noreferrer">Stokes3D_multixpu.jl</a> are single- and multi-xPU implementations, respectively. The multi-xPU implementation demonstrates ParallelStencil&#39;s capabilities to hide communication behind computation, which is performed with <a href="https://github.com/eth-cscs/ImplicitGlobalGrid.jl" target="_blank" rel="noreferrer">ImplicitGlobalGrid.jl</a> in this case. Results are obtained by running the multi-xPU miniapp on 8 Nvidia Titan Xm GPUs distributed across two physically distinct compute nodes. This multi-xPU application permits to leverage distributed memory parallelisation to enable large-scale 3-D calculations.</p><h2 id="Acoustic-wave-2-D-app" tabindex="-1">Acoustic wave 2-D app <a class="header-anchor" href="#Acoustic-wave-2-D-app" aria-label="Permalink to &quot;Acoustic wave 2-D app {#Acoustic-wave-2-D-app}&quot;">​</a></h2><blockquote><p>app: <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/acoustic2D.jl" target="_blank" rel="noreferrer">acoustic2D.jl</a></p></blockquote><p>The acoustic wave example solves acoustic waves in 2-D using the split velocity-pressure formulation: <img src="https://raw.githubusercontent.com/omlins/ParallelStencil.jl/main/miniapps/acoustic2D.gif" alt="Acoustic wave 2-D" style="display:block;margin:auto;width:100%;max-width:560px;"></p><p><em>The animation depicts the dynamical pressure field evolution as function of explicit time steps.</em></p><h2 id="Acoustic-wave-3-D-app" tabindex="-1">Acoustic wave 3-D app <a class="header-anchor" href="#Acoustic-wave-3-D-app" aria-label="Permalink to &quot;Acoustic wave 3-D app {#Acoustic-wave-3-D-app}&quot;">​</a></h2><blockquote><p>apps: <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/acoustic3D.jl" target="_blank" rel="noreferrer">acoustic3D.jl</a>, <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/acoustic_waves_multixpu/acoustic3D_multixpu.jl" target="_blank" rel="noreferrer">acoustic3D_multixpu.jl</a></p></blockquote><p>The acoustic wave example solves acoustic waves in 3-D using the split velocity-pressure formulation: <img src="https://raw.githubusercontent.com/omlins/ParallelStencil.jl/main/miniapps/acoustic_waves_multixpu/acoustic3D.gif" alt="Acoustic wave 3-D multi-xPU" style="display:block;margin:auto;width:100%;max-width:560px;"></p><p><em>The animation depicts the y-slice of the dynamical pressure field evolution as function of explicit time steps. <strong>The achieved numerical resolution is 1020x1020x1020 grid points in 3-D on 8 GPUs (i.e. a local domain size of 511x511x511 per GPU).</strong></em></p><p>The <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/acoustic3D.jl" target="_blank" rel="noreferrer">acoustic3D.jl</a> and <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/acoustic_waves_multixpu/acoustic3D_multixpu.jl" target="_blank" rel="noreferrer">acoustic3D_multixpu.jl</a> are single- and multi-xPU implementations, respectively. The multi-xPU implementation demonstrates ParallelStencil&#39;s capabilities to hide communication behind computation, which is performed with <a href="https://github.com/eth-cscs/ImplicitGlobalGrid.jl" target="_blank" rel="noreferrer">ImplicitGlobalGrid.jl</a> in this case. Results are obtained by running the multi-xPU miniapp on 8 Nvidia Titan Xm GPUs distributed across two physically distinct compute nodes. This multi-xPU application permits to leverage distributed memory parallelisation to enable large-scale 3-D calculations.</p><h2 id="Scalar-porosity-waves-2-D-app" tabindex="-1">Scalar porosity waves 2-D app <a class="header-anchor" href="#Scalar-porosity-waves-2-D-app" aria-label="Permalink to &quot;Scalar porosity waves 2-D app {#Scalar-porosity-waves-2-D-app}&quot;">​</a></h2><blockquote><p>app: <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/scalar_porowaves2D.jl" target="_blank" rel="noreferrer">scalar_porowaves2D.jl</a></p></blockquote><p>The scalar porosity waves example solves the scalar solitary wave equations in 2-D assuming total pressure to be lithostatic, thus eliminating the need to solve for the total pressure explicitly: <img src="https://raw.githubusercontent.com/omlins/ParallelStencil.jl/main/miniapps/porowaves2D_blob.gif" alt="Scalar porosity waves 2-D - blobs" style="display:block;margin:auto;width:100%;max-width:480px;"><img src="https://raw.githubusercontent.com/omlins/ParallelStencil.jl/main/miniapps/porowaves2D_chan.gif" alt="Scalar porosity waves 2-D - channels" style="display:block;margin:auto;width:100%;max-width:480px;"></p><p><em>The animation depicts the normalised porosity and effective pressure fields evolution as function of explicit time steps. Top row: compaction and decompaction rheology are identical, resulting in circular solitary waves rearranging into solitons of characteristic size. Bottom row: decompaction occurs at much faster rate compared to compaction, resulting in chimney-shaped features.</em></p><h2 id="Hydro-mechanical-porosity-waves-2-D-app" tabindex="-1">Hydro-mechanical porosity waves 2-D app <a class="header-anchor" href="#Hydro-mechanical-porosity-waves-2-D-app" aria-label="Permalink to &quot;Hydro-mechanical porosity waves 2-D app {#Hydro-mechanical-porosity-waves-2-D-app}&quot;">​</a></h2><blockquote><p>app: <a href="https://github.com/omlins/ParallelStencil.jl/blob/main/miniapps/HydroMech2D.jl" target="_blank" rel="noreferrer">HydroMech2D.jl</a></p></blockquote>',34)),i("p",null,[e[17]||(e[17]=t("The hydro-mechanical porosity wave example resolves solitary waves in 2-D owing to hydro-mechanical coupling, removing the lithostatic pressure assumption. The total and fluid pressure are explicitly computed from nonlinear Stokes and Darcy flow solvers, respectively [",-1)),o(a,null,{default:l(()=>[...e[16]||(e[16]=[i("a",{id:"Raess2019GJI-cite-1"},null,-1),i("a",{href:"/ParallelStencil.jl/v0.17/references#Raess2019GJI"},"9",-1)])]),_:1}),e[18]||(e[18]=t("]: ",-1)),e[19]||(e[19]=i("img",{src:"https://raw.githubusercontent.com/omlins/ParallelStencil.jl/main/miniapps/HydroMech2D.gif",alt:"Hydro-mechanical porosity waves 2-D",style:{display:"block",margin:"auto",width:"100%","max-width":"400px"}},null,-1))]),e[23]||(e[23]=i("p",null,[i("em",null,"The animation depicts the formation of fluid escape pipes in two-phase media, owing to decompaction weakening. Top row: evolution of the porosity distribution and effective pressure. Bottom row: Darcy flux (relative fluid to solid motion) and solid (porous matrix) deformation.")],-1))])}const w=n(u,[["render",h]]);export{y as __pageData,w as default};
